"use client";

import { cn } from "@/lib/utils";
import { Tooltip as TooltipPrimitive } from "radix-ui";
import type * as React from "react";

/**
 * Tooltip (tooltip-radix)
 *
 * A short text label that appears on hover or keyboard focus, built on Radix Tooltip with a theme-inverted bubble and arrow.
 *
 * Exports: Tooltip, TooltipContent, TooltipProvider, TooltipTrigger
 *
 * Props:
 * - TooltipProvider: React.ComponentProps<typeof TooltipPrimitive.Provider>
 *   - delayDuration: number (default 200). Milliseconds the pointer must rest before the tooltip opens.
 * - Tooltip: React.ComponentProps<typeof TooltipPrimitive.Root>
 * - TooltipTrigger: React.ComponentProps<typeof TooltipPrimitive.Trigger>
 * - TooltipContent: React.ComponentProps<typeof TooltipPrimitive.Content>
 *   - sideOffset: number (default 0). Distance in pixels between the trigger and the content.
 *
 * Theme tokens (shadcn names, from your theme): --background, --foreground, --radius, --radius-md.
 * Enter/exit animations use tw-animate-css utilities (import it in your global CSS).
 *
 * Accessibility:
 * - Opens on keyboard focus as well as hover, and Escape closes it.
 * - The content is linked to its trigger with aria-describedby, so screen readers announce it as a description.
 * - Use it for supplementary text only; never put interactive controls or essential information in a tooltip.
 * - Enter and exit animations are disabled under prefers-reduced-motion.
 *
 * Customize:
 * - TooltipProvider sets delayDuration for every tooltip inside it (200ms by default); pass 0 for dense toolbars.
 * - TooltipContent accepts side, align, and sideOffset to position the bubble.
 * - The bubble inverts the theme (bg-foreground with text-background), so it reads on any surface.
 */

function TooltipProvider({
  delayDuration = 200,
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Provider>) {
  return (
    <TooltipPrimitive.Provider
      data-slot="tooltip-provider"
      delayDuration={delayDuration}
      {...props}
    />
  );
}

function Tooltip({
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Root>) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
}

function TooltipTrigger({
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Trigger>) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

function TooltipContent({
  className,
  sideOffset = 0,
  children,
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Content>) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        className={cn(
          "fade-in-0 zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 isolate z-50 w-fit origin-(--radix-tooltip-content-transform-origin) animate-in text-balance rounded-md bg-foreground px-3 py-1.5 text-background text-xs data-[state=closed]:animate-out motion-reduce:animate-none",
          className
        )}
        data-slot="tooltip-content"
        sideOffset={sideOffset}
        {...props}
      >
        {children}
        <TooltipPrimitive.Arrow className="z-50 size-2.5 translate-y-[calc(-50%_-_2px)] rotate-45 rounded-[2px] bg-foreground fill-foreground" />
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };
